// AI Prompts: Write C# code that saves an Aspose.Cells workbook to PDF with PdfSaveOptions.RenderSolidGridlines set to true. | Compare worksheet.IsGridlinesVisible and PdfSaveOptions.RenderSolidGridlines for PDF generation. | Explain how to combine gridline visibility settings and PDF save options to produce solid gridlines in the output PDF.

using System;
using Aspose.Cells;

namespace AsposeCellsPdfGridlinesDemo
{
    // Shows how to produce a PDF with solid gridlines from an Excel workbook using Aspose.Cells for .NET by enabling worksheet gridlines and setting PdfSaveOptions.RenderSolidGridlines to true.
    public class Program
    {
        public static void Main()
        {
            try
            {
                // Create a new workbook and get the first worksheet
                Workbook workbook = new Workbook();
                Worksheet worksheet = workbook.Worksheets[0];

                // Populate some sample data so gridlines are visible
                worksheet.Cells["A1"].PutValue("Solid Gridlines Demo");
                worksheet.Cells["B2"].PutValue(123);
                worksheet.Cells["C3"].PutValue(DateTime.Now);

                // Ensure gridlines are visible in the worksheet
                worksheet.IsGridlinesVisible = true;

                // Save the workbook as a PDF. Gridlines will be rendered because they are visible in the worksheet.
                workbook.Save("SolidGridlinesOutput.pdf");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
